"""Столбцы: две серии рядом."""
import numpy as np


def draw(fig):
    names = ["Пн", "Вт", "Ср", "Чт", "Пт"]
    a, b = [5, 7, 3, 8, 6], [4, 6, 6, 5, 9]
    x = np.arange(len(names))
    ax = fig.add_subplot()
    ax.bar(x - 0.2, a, 0.4, label="утро")
    ax.bar(x + 0.2, b, 0.4, label="вечер")
    ax.set_xticks(x, names)
    ax.set_ylabel("задач закрыто")
    ax.set_title("Неделя")
    ax.legend()


if __name__ == "__main__":
    from mpldemo import run
    run(draw)
